const params = $('Set Orchestrator Params').first().json;
const items = $input.all();

const registered = items
  .map(item => item.json)
  .filter(item => item && (item.asset_id || item.assetId));

const processed = registered.filter(item =>
  item.moveStatus === 'processed' ||
  item.status === 'raw' ||
  item.asset_id ||
  item.assetId
);

const selected = processed[processed.length - 1];

if (!params.autoPromoteLatest || !selected) {
  return [{
    json: {
      orchestratorStatus: 'registered_only',
      reason: !params.autoPromoteLatest ? 'autoPromoteLatest is false' : 'No registered asset returned',
      registeredCount: registered.length,
      params,
      registered
    }
  }];
}

return [{
  json: {
    ...params,
    assetId: selected.asset_id || selected.assetId,
    selectedAsset: selected,
    registeredCount: registered.length,
    registered
  }
}];

const params = $('Set Orchestrator Params').first().json;
return [{
  json: {
    avatar: params.avatar,
    scene: params.scene,
    assetType: params.assetType,
    baseUrl: params.baseUrl
  }
}];

const canonicalItems = $input.all().map(item => item.json || {});
const canonical = canonicalItems[0] || null;
const selected = $('Select Asset To Promote').first().json || {};

const allReturned = Array.isArray(selected.registered) ? selected.registered : [];

const normalized = allReturned.map(item => {
  const assetId = item.assetId || item.asset_id || null;
  const assetType = item.assetType || item.asset_type || item.asset_type_returned || null;
  const objectPath = item.objectPath || item.object_path || null;
  const fileName = item.file?.name || item.file_name || null;
  const sourceFileName = item.sourceFile?.name || item.source_file_name || null;
  const sourceFileDirectory = item.sourceFile?.directory || item.source_file_directory || null;

  return {
    assetId,
    sha256: item.sha256 || null,
    avatar: item.avatar || null,
    scene: item.scene || null,
    assetType,
    status: item.status || null,
    isCanonical: item.isCanonical ?? item.is_canonical ?? false,
    canonicalGroup: item.canonicalGroup || item.canonical_group || null,
    fileName,
    sourceFileName,
    sourceFileDirectory,
    objectPath,
    bucket: item.storage?.bucket || item.bucket || null,
    mimeType: item.file?.mimeType || item.mime_type || item.mimeType || null,
    moveStatus: item.moveStatus || null,
    movedFrom: item.movedFrom || null,
    movedTo: item.movedTo || null,
    duplicateReason: item.duplicateReason || null,
    duplicated: Boolean(item.duplicated || item.duplicated_in_db || item.moveStatus === 'duplicate')
  };
});

const registered = normalized.filter(item => item.assetId && !item.duplicated);
const duplicates = normalized.filter(item => item.duplicated);

const canonicalCompact = canonical && canonical.found ? {
  assetId: canonical.assetId || canonical.asset_id || null,
  avatar: canonical.avatar || null,
  scene: canonical.scene || null,
  assetType: canonical.assetType || canonical.asset_type || null,
  url: canonical.url || null,
  bucket: canonical.bucket || null,
  objectPath: canonical.objectPath || canonical.object_path || null,
  mimeType: canonical.mimeType || canonical.mime_type || null,
  status: canonical.status || null,
  sha256: canonical.sha256 || null,
  canonicalGroup: canonical.canonicalGroup || canonical.canonical_group || null,
  createdAt: canonical.createdAt || canonical.created_at || null
} : null;

const promotedAssetId = selected.assetId || canonicalCompact?.assetId || null;
const canonicalUrl = canonicalCompact?.url || null;

return [{
  json: {
    status: canonicalCompact ? 'completed' : 'completed_without_canonical_result',
    registeredCount: registered.length,
    duplicatesCount: duplicates.length,
    processedCount: registered.filter(item => item.moveStatus === 'processed').length,
    promotedAssetId,
    canonicalUrl,
    canonical: canonicalCompact,
    registered,
    duplicates
  }
}];

const data = $input.first().json || {};
const allReturned = Array.isArray(data.registered) ? data.registered : [];

const normalized = allReturned.map(item => ({
  assetId: item.assetId || item.asset_id || null,
  sha256: item.sha256 || null,
  avatar: item.avatar || null,
  scene: item.scene || null,
  assetType: item.assetType || item.asset_type || item.asset_type_returned || null,
  status: item.status || null,
  canonicalGroup: item.canonicalGroup || item.canonical_group || null,
  fileName: item.file?.name || item.file_name || null,
  sourceFileName: item.sourceFile?.name || item.source_file_name || null,
  sourceFileDirectory: item.sourceFile?.directory || item.source_file_directory || null,
  objectPath: item.objectPath || item.object_path || null,
  moveStatus: item.moveStatus || null,
  movedFrom: item.movedFrom || null,
  movedTo: item.movedTo || null,
  duplicateReason: item.duplicateReason || null,
  duplicated: Boolean(item.duplicated || item.duplicated_in_db || item.moveStatus === 'duplicate')
}));

const registered = normalized.filter(item => item.assetId && !item.duplicated);
const duplicates = normalized.filter(item => item.duplicated);

return [{
  json: {
    status: data.orchestratorStatus || 'registered_only',
    reason: data.reason || null,
    registeredCount: registered.length,
    duplicatesCount: duplicates.length,
    processedCount: registered.filter(item => item.moveStatus === 'processed').length,
    promotedAssetId: null,
    canonicalUrl: null,
    canonical: null,
    registered,
    duplicates
  }
}];
